39	    @Test public void createsFormData() {
40	        String html = "<form><input name='one' value='two'><select name='three'><option value='not'>" +
41	                "<option value='four' selected><option value='five' selected><textarea name=six>seven</textarea>" +
42	                "<input name='seven' type='radio' value='on' checked><input name='seven' type='radio' value='off'>" +
