194	    @Test public void formSubmissionCarriesCookiesFromSession() throws IOException {
195	        String echoUrl = TestServer.origin().echo.url();
196	        Document cookieDoc = Jsoup.connect(TestServer.origin().cookie.url())
197	            .data(CookieRoute.SetCookiesParam, "1")
198	            .get();
199	        Document formDoc = cookieDoc.connection().newRequest() // carries cookies from above set
200	            .url(TestServer.origin().file.url("/htmltests/upload-form.html"))
201	            .get();
202	        FormElement form = formDoc.select("form").forms().get(0);
203	        Document echo = form.submit().post();
204	
205	        assertEquals(echoUrl, echo.location());
206	        Elements els = echo.select("th:contains(Cookie: One)");
207	        // ensure that the cookies are there and in path-specific order (two with same name)
208	        assertEquals("Echo", els.get(0).nextElementSibling().text());
209	        assertEquals("Root", els.get(1).nextElementSibling().text());
210	
211	        // make sure that the session following kept unique requests
212	        assertTrue(cookieDoc.connection().response().url().toExternalForm().contains("Cookie"));
213	        assertTrue(formDoc.connection().response().url().toExternalForm().contains("upload-form"));
214	        assertTrue(echo.connection().response().url().toExternalForm().contains("Echo"));
215	    }
