                                data.add(HttpConnection.KeyVal.create(name, option.val()));
                                deterministic = true;
                                break;
                            }
                        }
                    }
                } else if (!multiple) {
                    // nothing marked selected: a single select defaults to its first enabled option
                    for (Element option : el.select("option")) {
                        if (isEnabledOption(option)) {
                            data.add(HttpConnection.KeyVal.create(name, option.val()));
